```tsx
import { useId } from "react";
import "./SettingsToggleRow.css";

export interface SettingsToggleRowProps {
  label: string;
  hint: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

export function SettingsToggleRow({
  label,
  hint,
  checked,
  onChange,
}: SettingsToggleRowProps) {
  const labelId = useId();
  const hintId = useId();

  return (
    <div className="settings-toggle-row">
      <div className="settings-toggle-row__text">
        <span id={labelId} className="settings-toggle-row__label">
          {label}
        </span>
        <span id={hintId} className="settings-toggle-row__hint">
          {hint}
        </span>
      </div>
      <button
        type="button"
        className="settings-toggle-row__switch"
        aria-pressed={checked}
        aria-labelledby={labelId}
        aria-describedby={hintId}
        onClick={() => onChange(!checked)}
      >
        <span className="settings-toggle-row__knob" aria-hidden="true" />
      </button>
    </div>
  );
}
```

```css
/* Focus outline comes from the global :focus-visible rule; this file never removes it. */

.settings-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: clamp(0.75rem, 2vw, 1.5rem);
  padding: clamp(0.75rem, 1.5vw, 1rem) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
}

.settings-toggle-row__text {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
}

.settings-toggle-row__label {
  font-size: clamp(0.95rem, 1.2vw, 1.125rem);
  color: var(--ink);
}

.settings-toggle-row__hint {
  font-size: clamp(0.8rem, 1vw, 0.95rem);
  color: var(--muted);
}

.settings-toggle-row__switch {
  position: relative;
  flex: 0 0 auto;
  box-sizing: border-box;
  width: clamp(2.75rem, 4vw, 3.25rem);
  height: clamp(1.5rem, 2.2vw, 1.75rem);
  padding: 0;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: var(--axon-ahead);
  cursor: pointer;
  font: inherit;
  transition: background-color 180ms ease, border-color 180ms ease;
}

.settings-toggle-row__switch[aria-pressed="true"] {
  background: var(--myelin);
  border-color: var(--myelin);
}

.settings-toggle-row__knob {
  position: absolute;
  top: 50%;
  left: 0.2rem;
  width: calc(clamp(1.5rem, 2.2vw, 1.75rem) - 0.6rem);
  height: calc(clamp(1.5rem, 2.2vw, 1.75rem) - 0.6rem);
  border-radius: 999px;
  background: var(--slide);
  transform: translateY(-50%);
  transition: transform 180ms ease;
}

.settings-toggle-row__switch[aria-pressed="true"] .settings-toggle-row__knob {
  transform: translate(
      calc(clamp(2.75rem, 4vw, 3.25rem) - clamp(1.5rem, 2.2vw, 1.75rem) - 0.4rem),
      -50%
    );
}

:root[data-motion="reduce"] .settings-toggle-row__switch,
:root[data-motion="reduce"] .settings-toggle-row__knob {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .settings-toggle-row__switch,
  .settings-toggle-row__knob {
    transition: none;
  }
}
